import re

COLS = ['Tra', 'Pri', 'Pro', 'Tcl', 'Status', 'Purgeability', 'Prf', 'Taskdatakey', 'Taskdataloc', 'Isolatest', 'Indoubt', 'Indoubtwait']
F1 = ['Status', 'Purgeability']
F2 = ['Taskdatakey', 'Taskdataloc', 'Isolatest', 'Indoubt', 'Indoubtwait']

def fill(rec, rest, flagnames):
    for k, v in re.findall(r'(\w+)\(\s*([^)]*?)\s*\)', rest):
        if k in rec:
            rec[k] = v
    flags = re.sub(r'\w+\([^)]*\)', ' ', rest).split()
    for n, f in zip(flagnames, flags):
        rec[n] = f

def parse(lines):
    recs = []
    used = []
    skip = []
    kv = {}
    kvl = []
    cur = None
    for i, l in enumerate(lines):
        s = l.strip()
        if not s:
            continue
        m = re.match(r'^\+?\s*(?P<rest>Tra\(.*)$', s)
        if m:
            cur = dict((c, '') for c in COLS)
            fill(cur, m.group('rest'), F1)
            recs.append(cur)
            used.append(i)
            continue
        m = re.match(r'^\+?\s*(?P<rest>Prf\(.*)$', s)
        if m and cur is not None:
            fill(cur, m.group('rest'), F2)
            used.append(i)
            continue
        if re.search(r'\b(SYSID|APPLID)=', s):
            for k, v in re.findall(r'(\w+)=(\S+)', s):
                kv[k] = v
            kvl.append(i)
            continue
        if re.match(r'^RESPONSE:', s):
            for k, v in re.findall(r'(RESPONSE|TIME|DATE):\s*(\S+)', s):
                kv[k] = v
            kvl.append(i)
            continue
        if re.match(r'^(I\s|INQ|STATUS:|PF\s|PF\d)', s):
            skip.append(i)
            continue
    blocks = []
    if recs:
        blocks.append({'name': 'transactions', 'kind': 'table', 'lines': used, 'records': recs})
    if kv:
        blocks.append({'name': 'summary', 'kind': 'kv', 'lines': kvl, 'records': [kv]})
    return {'blocks': blocks, 'skip': skip}
